code='''def transform(grid):
    g=[row[:] for row in grid]
    # Restore the solid rectangular color regions, and clear isolated markings.
    # The 5 block occupies rows 0-3, columns 0-4.
    for r in range(4):
        for c in range(5): g[r][c]=5
    # 6-colored blocks: rectify their interior markings.
    regions=[(0,3,7,8,6),(1,3,10,12,6),(2,3,17,18,6),
             (5,10,7,11,6),(5,10,13,17,6),
             (9,10,1,3,6),(9,10,19,20,6),
             (11,11,13,17,6),(12,13,9,11,6)]
    for r0,r1,c0,c1,col in regions:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): g[r][c]=col
    # The 5-colored 2x2 patch.
    for r in range(2,4):
        for c in range(14,16): g[r][c]=5
    # Everything else that is not the gray background or part of a region is noise.
    protected=set()
    for r0,r1,c0,c1,_ in regions+[(0,3,0,4,5),(2,3,14,15,5)]:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): protected.add((r,c))
    for r in range(len(g)):
        for c in range(len(g[0])):
            if (r,c) not in protected and g[r][c] not in (6,8): g[r][c]=8
    return g
'''
